  - {name: risk.order_evaluated.v1, kind: event, publisher: RiskEngine, consumers: [OrderApplication, Audit, Metrics], schema: events/risk.order_evaluated.v1.schema.json, status: active}
  - {name: risk.order_evaluated.v2, kind: event, publisher: RiskEngine, consumers: [OrderApplication, Audit, Metrics], schema: events/risk.order_evaluated.v2.schema.json, status: active}
