  - {name: risk.rule_set_activated.v1, kind: event, publisher: ConfigService, consumers: [RiskEngine, Audit], status: planned}
  - {name: oms.order_registered.v1, kind: event, publisher: OMS, consumers: [Risk, StrategyRuntime, Audit], schema: events/oms.order_registered.v1.schema.json, status: active}
  - {name: oms.order_suspended.v1, kind: event, publisher: OMS, consumers: [Reconciliation, ControlPlane, Alert], status: planned}
  - {name: execution.attempt_started.v1, kind: event, publisher: ExecutionEngine, consumers: [OMS, Audit], schema: events/execution.attempt_started.v1.schema.json, status: active}
  - {name: execution.outcome_unknown.v1, kind: event, publisher: ExecutionEngine, consumers: [OMS, Reconciliation, Alert], schema: events/execution.outcome_unknown.v1.schema.json, status: active}
  - {name: broker.order_reported.v1, kind: event, publisher: BrokerAdapter, consumers: [OMS, Reconciliation, Audit], schema: events/broker.order_reported.v1.schema.json, status: active}
  - {name: ledger.trade_posted.v1, kind: event, publisher: AccountLedger, consumers: [Portfolio, Risk, Audit], schema: events/ledger.trade_posted.v1.schema.json, status: active}
  - {name: ledger.adjustment_posted.v1, kind: event, publisher: AccountLedger, consumers: [Portfolio, Risk, Audit], status: planned}
  - {name: portfolio.position_changed.v1, kind: event, publisher: PortfolioProjection, consumers: [Risk, StrategyRuntime, API], schema: events/portfolio.position_changed.v1.schema.json, status: active}
  - {name: portfolio.snapshot_created.v1, kind: event, publisher: PortfolioProjection, consumers: [Recovery, Risk], status: planned}
  - {name: account.snapshot_observed.v1, kind: event, publisher: BrokerAdapter, consumers: [Reconciliation, Risk], status: planned}
  - {name: portfolio.snapshot_observed.v1, kind: event, publisher: BrokerAdapter, consumers: [Reconciliation, Risk], status: planned}
  - {name: reconciliation.case_opened.v1, kind: event, publisher: Reconciliation, consumers: [ControlPlane, Alert], status: planned}
  - {name: reconciliation.case_resolved.v1, kind: event, publisher: Reconciliation, consumers: [OMS, Ledger, Audit], status: planned}
  - {name: system.mode_changed.v1, kind: event, publisher: TradingCore, consumers: [TradingComponents, Audit], schema: events/system.mode_changed.v1.schema.json, status: active}
  - {name: system.component_health_changed.v1, kind: event, publisher: HealthService, consumers: [ControlPlane, Alert, Audit], schema: events/system.component_health_changed.v1.schema.json, status: active}
  - {name: system.kill_switch_changed.v1, kind: event, publisher: ControlPlane, consumers: [Risk, OMS, Execution, Audit], schema: events/system.kill_switch_changed.v1.schema.json, status: active}
  - {name: config.version_activated.v1, kind: event, publisher: ConfigService, consumers: [AffectedComponents, Audit], schema: events/config.version_activated.v1.schema.json, status: active, semantics: ActiveVersion_authority_change_only, activation_kinds: [CANDIDATE_COMMIT, ROLLBACK_RESTORE]}
rules:
  active_requires_schema: true
  published_name_reuse: forbidden
  planned_message_must_be_activated_by_spec_change_task: true
internal_contracts:
