  - {id: CONTRACT-BACKTEST-PARITY-SEMANTIC-V1, schema: simulation/backtest-parity.semantic-validation.v1.yaml, status: draft, owner: Backtest}
  - {id: CONTRACT-MARKET-DATA-V1, schema: market/market-data.v1.schema.json, status: draft, owner: MarketData}
  - {id: CONTRACT-MARKET-SEMANTIC-VALIDATION-V1, schema: market/market-data.semantic-validation.v1.yaml, status: draft, owner: MarketData}
  - {id: CONTRACT-LEDGER-ACCOUNTING-V1, schema: ledger/ledger-accounting.v1.schema.json, status: draft, owner: AccountLedger}
  - {id: CONTRACT-PORTFOLIO-PROJECTION-V1, schema: portfolio/portfolio-projection.v1.schema.json, status: draft, owner: PortfolioProjection}
  - {id: CONTRACT-RECONCILIATION-V1, schema: reconciliation/reconciliation.v1.schema.json, status: draft, owner: Reconciliation}
  - {id: CONTRACT-CONTROL-PLANE-V1, schema: control/control-plane.v1.schema.json, status: draft, owner: ControlPlane}
  - {id: CONTRACT-CONTROL-SEMANTIC-VALIDATION-V1, schema: control/control-semantic-validation.v1.yaml, status: draft, owner: ControlPlane}
  - {id: CONTRACT-CONTROL-COMBINED-MESSAGE-V1, schema: control/combined-control-message.v1.schema.json, status: draft, owner: ControlPlane}
internal_rules:
  schema_required: true
  schema_and_semantic_validation_required: true
  dto_type_reuse: forbidden

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:quantiqmt:event:risk.order_evaluated:v2",
  "title": "RiskOrderEvaluatedPayloadV2",
  "description": "Authoritative RiskAuditOutput structure. Draft 2020-12 validates field structure only. Cross-field ordering, uniqueness, cardinality, RuleResult/RuleTiming identity, completed_rule_count, timeout, and latency-sum invariants are mandatory under the PORTS-RISK RiskAuditSemanticValidator contract. A schema-valid object that fails semantic validation is not a valid RiskAuditOutput and MUST NOT be persisted, projected to v1, published, or used to enter Execution.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "decision", "evaluated_at", "total_latency_us", "evaluation_timeout_us", "completed_rule_count", "rule_timings"],
  "properties": {
    "schema_version": {"const": 1},
    "decision": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schema_version", "decision_id", "decision_origin", "input_version", "semantic_decision_hash", "order_id", "expected_order_version", "decision", "primary_reason_code", "error_code", "rule_set_version", "rule_set_hash", "snapshot_states", "rule_results"],
      "properties": {
        "schema_version": {"const": 1},
        "decision_id": {"type": "string", "format": "uuid", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
        "decision_origin": {"enum": ["EVALUATOR", "INPUT_GUARD", "TIMEOUT_GUARD"]},
        "input_version": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "semantic_decision_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "order_id": {"type": "string", "format": "uuid", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
        "expected_order_version": {"type": "integer", "minimum": 1},
        "decision": {"enum": ["PASS", "REJECT"]},
        "primary_reason_code": {
          "enum": ["RISK_ALL_APPLICABLE_RULES_PASSED", "RISK_RULE_PASSED", "RISK_RULE_NOT_APPLICABLE", "RISK_RULE_BREACH", "RISK_HARD_LIMIT_BREACH", "RISK_TRADING_DISABLED", "RISK_INSTRUMENT_NOT_ALLOWED", "RISK_SNAPSHOT_STALE", "RISK_SNAPSHOT_PARTIAL", "RISK_SNAPSHOT_TIMEOUT", "RISK_SNAPSHOT_UNAVAILABLE", "RISK_SNAPSHOT_VERSION_MISMATCH", "RISK_RULE_SET_VERSION_MISMATCH", "RISK_INPUT_INVALID", "RISK_RULE_SET_INVALID", "RISK_REDUCTION_EVIDENCE_INVALID", "RISK_REDUCE_ONLY_EXCEPTION_APPLIED", "RISK_EVALUATION_TIMEOUT"]
        },
        "error_code": {"type": ["string", "null"], "pattern": "^QQ-RISK-40(0[1-9]|1[01])$"},
        "rule_set_version": {"type": "string", "minLength": 1, "maxLength": 64},
        "rule_set_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "snapshot_states": {
          "type": "object",
          "additionalProperties": false,
          "required": ["account", "portfolio", "market"],
          "properties": {
            "account": {
              "type": "object",
              "additionalProperties": false,
              "required": ["snapshot_version", "quality", "age_ms", "max_age_ms"],
              "properties": {
                "snapshot_version": {"type": "string", "minLength": 1, "maxLength": 128},
                "quality": {"enum": ["FRESH", "STALE", "PARTIAL", "TIMEOUT", "UNAVAILABLE", "VERSION_MISMATCH"]},
                "age_ms": {"type": ["integer", "null"], "minimum": 0},
                "max_age_ms": {"type": "integer", "minimum": 0}
              }
            },
            "portfolio": {
              "type": "object",
              "additionalProperties": false,
              "required": ["snapshot_version", "quality", "age_ms", "max_age_ms"],
              "properties": {
                "snapshot_version": {"type": "string", "minLength": 1, "maxLength": 128},
                "quality": {"enum": ["FRESH", "STALE", "PARTIAL", "TIMEOUT", "UNAVAILABLE", "VERSION_MISMATCH"]},
                "age_ms": {"type": ["integer", "null"], "minimum": 0},
                "max_age_ms": {"type": "integer", "minimum": 0}
              }
            },
            "market": {
              "type": "object",
              "additionalProperties": false,
              "required": ["snapshot_version", "quality", "age_ms", "max_age_ms"],
              "properties": {
                "snapshot_version": {"type": "string", "minLength": 1, "maxLength": 128},
                "quality": {"enum": ["FRESH", "STALE", "PARTIAL", "TIMEOUT", "UNAVAILABLE", "VERSION_MISMATCH"]},
                "age_ms": {"type": ["integer", "null"], "minimum": 0},
                "max_age_ms": {"type": "integer", "minimum": 0}
              }
            }
          }
        },
        "rule_results": {
          "type": "array",
          "minItems": 1,
          "maxItems": 8192,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["evaluation_index", "rule_id", "phase", "scope", "scope_id", "priority", "metric", "result", "reason_code", "measured_value", "limit_value", "exception_applied"],
            "properties": {
              "evaluation_index": {"type": "integer", "minimum": 0},
              "rule_id": {"type": "string", "minLength": 1, "maxLength": 128},
              "phase": {"enum": ["INPUT_VALIDITY", "SNAPSHOT_VALIDITY", "SYSTEM_HARD_LIMIT", "SCOPED_RULE", "TIMEOUT_GUARD"]},
              "scope": {"enum": ["SYSTEM", "ACCOUNT", "PORTFOLIO", "STRATEGY", "INSTRUMENT"]},
              "scope_id": {"type": ["string", "null"], "minLength": 1, "maxLength": 128},
              "priority": {"type": "integer", "minimum": 0, "maximum": 1000000},
              "metric": {"type": ["string", "null"], "minLength": 1, "maxLength": 64},
              "result": {"enum": ["PASS", "REJECT", "NOT_APPLICABLE"]},
              "reason_code": {
                "enum": ["RISK_ALL_APPLICABLE_RULES_PASSED", "RISK_RULE_PASSED", "RISK_RULE_NOT_APPLICABLE", "RISK_RULE_BREACH", "RISK_HARD_LIMIT_BREACH", "RISK_TRADING_DISABLED", "RISK_INSTRUMENT_NOT_ALLOWED", "RISK_SNAPSHOT_STALE", "RISK_SNAPSHOT_PARTIAL", "RISK_SNAPSHOT_TIMEOUT", "RISK_SNAPSHOT_UNAVAILABLE", "RISK_SNAPSHOT_VERSION_MISMATCH", "RISK_RULE_SET_VERSION_MISMATCH", "RISK_INPUT_INVALID", "RISK_RULE_SET_INVALID", "RISK_REDUCTION_EVIDENCE_INVALID", "RISK_REDUCE_ONLY_EXCEPTION_APPLIED", "RISK_EVALUATION_TIMEOUT"]
              },
              "measured_value": {
                "oneOf": [
                  {"type": "null"},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value", "currency"], "properties": {"kind": {"const": "DECIMAL"}, "value": {"type": "string", "pattern": "^-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"}, "currency": {"type": ["string", "null"], "pattern": "^[A-Z]{3}$"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "INTEGER"}, "value": {"type": "integer"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "BOOLEAN"}, "value": {"type": "boolean"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "STRING"}, "value": {"type": "string", "minLength": 1, "maxLength": 128}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "values"], "properties": {"kind": {"const": "STRING_SET"}, "values": {"type": "array", "items": {"type": "string", "minLength": 1, "maxLength": 128}, "minItems": 1, "maxItems": 10000, "uniqueItems": true}}}
                ]
              },
              "limit_value": {
                "oneOf": [
                  {"type": "null"},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value", "currency"], "properties": {"kind": {"const": "DECIMAL"}, "value": {"type": "string", "pattern": "^-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"}, "currency": {"type": ["string", "null"], "pattern": "^[A-Z]{3}$"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "INTEGER"}, "value": {"type": "integer"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "BOOLEAN"}, "value": {"type": "boolean"}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "STRING"}, "value": {"type": "string", "minLength": 1, "maxLength": 128}}},
                  {"type": "object", "additionalProperties": false, "required": ["kind", "values"], "properties": {"kind": {"const": "STRING_SET"}, "values": {"type": "array", "items": {"type": "string", "minLength": 1, "maxLength": 128}, "minItems": 1, "maxItems": 10000, "uniqueItems": true}}}
                ]
              },
              "exception_applied": {"type": "boolean"}
            }
          }
        }
      },
      "allOf": [
        {"if": {"properties": {"decision": {"const": "PASS"}}}, "then": {"properties": {"primary_reason_code": {"const": "RISK_ALL_APPLICABLE_RULES_PASSED"}, "error_code": {"type": "null"}, "decision_origin": {"const": "EVALUATOR"}}}},
        {"if": {"properties": {"decision": {"const": "REJECT"}}}, "then": {"properties": {"error_code": {"type": "string"}}}}
      ]
    },
    "evaluated_at": {"type": "string", "format": "date-time", "pattern": "Z$"},
    "total_latency_us": {"type": "integer", "minimum": 0},
    "evaluation_timeout_us": {"type": "integer", "minimum": 1, "maximum": 4000},
    "completed_rule_count": {"type": "integer", "minimum": 0, "maximum": 8192},
    "rule_timings": {
      "description": "Structurally valid timings; PORTS-RISK additionally requires ordered one-to-one identity with decision.rule_results, including the synthetic timeout guard timing.",
      "type": "array",
      "minItems": 1,
      "maxItems": 8192,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["evaluation_index", "rule_id", "latency_us"],
        "properties": {
          "evaluation_index": {"type": "integer", "minimum": 0},
          "rule_id": {"type": "string", "minLength": 1, "maxLength": 128},
          "latency_us": {"type": "integer", "minimum": 0}
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:quantiqmt:contract:risk-input:v1",
  "title": "RiskInputV1",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "input_version", "evaluation_time", "valuation_currency", "rule_set_version", "rule_set_hash", "order", "account", "portfolio", "market"],
  "properties": {
    "schema_version": {"const": 1},
    "input_version": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "evaluation_time": {"type": "string", "format": "date-time", "pattern": "Z$"},
    "valuation_currency": {"$ref": "#/$defs/currency"},
    "rule_set_version": {"type": "string", "minLength": 1, "maxLength": 64},
    "rule_set_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "order": {"$ref": "#/$defs/orderSnapshot"},
    "account": {"$ref": "#/$defs/accountSnapshot"},
    "portfolio": {"$ref": "#/$defs/portfolioSnapshot"},
    "market": {"$ref": "#/$defs/marketSnapshot"}
  },
  "$defs": {
    "uuid": {
      "type": "string",
      "format": "uuid",
      "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
    },
    "currency": {
      "type": "string",
      "pattern": "^[A-Z]{3}$"
    },
    "decimal": {
      "type": "string",
      "pattern": "^-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"
    },
    "nonNegativeDecimal": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"
    },
    "nullableDecimal": {
      "type": ["string", "null"],
      "pattern": "^-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"
    },
    "snapshotMetadata": {
      "type": "object",
      "additionalProperties": false,
      "required": ["source", "snapshot_version", "schema_version", "aggregate_version", "as_of", "trading_day", "quality", "missing_fields", "checksum"],
      "properties": {
        "source": {"type": "string", "minLength": 1, "maxLength": 128},
        "snapshot_version": {"type": "string", "minLength": 1, "maxLength": 128},
        "schema_version": {"const": 1},
        "aggregate_version": {"type": ["integer", "null"], "minimum": 1},
        "as_of": {"type": "string", "format": "date-time", "pattern": "Z$"},
        "trading_day": {"type": "string", "format": "date"},
        "quality": {"enum": ["FRESH", "STALE", "PARTIAL", "TIMEOUT", "UNAVAILABLE"]},
        "missing_fields": {
          "type": "array",
          "items": {"type": "string", "minLength": 1, "maxLength": 128},
          "uniqueItems": true,
          "maxItems": 64
        },
        "checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"}
      },
      "allOf": [
        {"if": {"properties": {"quality": {"enum": ["FRESH", "STALE"]}}}, "then": {"properties": {"missing_fields": {"maxItems": 0}}}},
        {"if": {"properties": {"quality": {"const": "PARTIAL"}}}, "then": {"properties": {"missing_fields": {"minItems": 1}}}}
      ]
    },
    "reductionEvidence": {
      "type": ["object", "null"],
      "additionalProperties": false,
      "required": ["classification", "position_snapshot_version", "position_quantity_before", "reserved_reduce_quantity", "max_reducible_quantity", "projected_position_quantity", "would_flip_position"],
      "properties": {
        "classification": {"const": "VERIFIED_REDUCE_ONLY"},
        "position_snapshot_version": {"type": "string", "minLength": 1, "maxLength": 128},
        "position_quantity_before": {"type": "integer"},
        "reserved_reduce_quantity": {"type": "integer", "minimum": 0},
        "max_reducible_quantity": {"type": "integer", "minimum": 0},
        "projected_position_quantity": {"type": "integer"},
        "would_flip_position": {"const": false}
      }
    },
    "orderSnapshot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schema_version", "checksum", "order_id", "aggregate_version", "intent_id", "account_id", "portfolio_id", "strategy_id", "strategy_version", "instrument_id", "side", "position_effect", "order_type", "quantity", "limit_price", "time_in_force", "registered_at", "market_data_version", "risk_effect", "reduction_evidence"],
      "properties": {
        "schema_version": {"const": 1},
        "checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "order_id": {"$ref": "#/$defs/uuid"},
        "aggregate_version": {"type": "integer", "minimum": 1},
        "intent_id": {"$ref": "#/$defs/uuid"},
        "account_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "portfolio_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "strategy_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "strategy_version": {"type": "string", "minLength": 1, "maxLength": 64},
        "instrument_id": {"type": "string", "minLength": 1, "maxLength": 64},
        "side": {"enum": ["BUY", "SELL"]},
        "position_effect": {"enum": ["OPEN", "CLOSE", "AUTO"]},
        "order_type": {"enum": ["LIMIT", "MARKET", "BEST"]},
        "quantity": {"type": "integer", "minimum": 1},
        "limit_price": {"type": ["string", "null"], "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
        "time_in_force": {"enum": ["DAY", "IOC", "FOK"]},
        "registered_at": {"type": "string", "format": "date-time", "pattern": "Z$"},
        "market_data_version": {"type": "string", "minLength": 1, "maxLength": 128},
        "risk_effect": {"enum": ["INCREASE", "REDUCE", "UNKNOWN"]},
        "reduction_evidence": {"$ref": "#/$defs/reductionEvidence"}
      },
      "allOf": [
        {"if": {"properties": {"order_type": {"const": "LIMIT"}}}, "then": {"properties": {"limit_price": {"type": "string", "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"}}}},
        {"if": {"properties": {"risk_effect": {"const": "REDUCE"}}}, "then": {"properties": {"reduction_evidence": {"type": "object"}}}},
        {"if": {"properties": {"risk_effect": {"enum": ["INCREASE", "UNKNOWN"]}}}, "then": {"properties": {"reduction_evidence": {"type": "null"}}}}
      ]
    },
    "accountSnapshot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["metadata", "account_id", "currency", "equity", "available_cash", "projected_available_cash", "margin_used", "daily_loss", "open_order_notional"],
      "properties": {
        "metadata": {"$ref": "#/$defs/snapshotMetadata"},
        "account_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "currency": {"$ref": "#/$defs/currency"},
        "equity": {"$ref": "#/$defs/nullableDecimal"},
        "available_cash": {"$ref": "#/$defs/nullableDecimal"},
        "projected_available_cash": {"$ref": "#/$defs/nullableDecimal"},
        "margin_used": {"$ref": "#/$defs/nullableDecimal"},
        "daily_loss": {"$ref": "#/$defs/nullableDecimal"},
        "open_order_notional": {"$ref": "#/$defs/nullableDecimal"}
      }
    },
    "scopeMetrics": {
      "type": "object",
      "additionalProperties": false,
      "required": ["scope", "scope_id", "enabled", "position_quantity", "projected_position_quantity", "projected_gross_exposure", "projected_net_exposure", "projected_leverage", "activity_window_ms", "order_count_window", "cancel_ratio_bps"],
      "properties": {
        "scope": {"enum": ["ACCOUNT", "PORTFOLIO", "STRATEGY", "INSTRUMENT"]},
        "scope_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "enabled": {"type": ["boolean", "null"]},
        "position_quantity": {"type": ["integer", "null"]},
        "projected_position_quantity": {"type": ["integer", "null"]},
        "projected_gross_exposure": {"$ref": "#/$defs/nullableDecimal"},
        "projected_net_exposure": {"$ref": "#/$defs/nullableDecimal"},
        "projected_leverage": {"$ref": "#/$defs/nullableDecimal"},
        "activity_window_ms": {"type": "integer", "minimum": 1, "maximum": 86400000},
        "order_count_window": {"type": ["integer", "null"], "minimum": 0},
        "cancel_ratio_bps": {"type": ["integer", "null"], "minimum": 0, "maximum": 10000}
      }
    },
    "portfolioSnapshot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["metadata", "portfolio_id", "account_id", "base_currency", "scope_metrics"],
      "properties": {
        "metadata": {"$ref": "#/$defs/snapshotMetadata"},
        "portfolio_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "account_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "base_currency": {"$ref": "#/$defs/currency"},
        "scope_metrics": {"type": "array", "items": {"$ref": "#/$defs/scopeMetrics"}, "minItems": 4, "maxItems": 4}
      }
    },
    "marketSnapshot": {
      "type": "object",
      "additionalProperties": false,
      "required": ["metadata", "instrument_id", "trading_status", "currency", "risk_price", "risk_price_source", "reference_price", "price_deviation_bps", "upper_price_limit", "lower_price_limit"],
      "properties": {
        "metadata": {"$ref": "#/$defs/snapshotMetadata"},
        "instrument_id": {"type": "string", "minLength": 1, "maxLength": 64},
        "trading_status": {"enum": ["TRADING", "HALTED", "SUSPENDED", "CLOSED", "UNKNOWN"]},
        "currency": {"$ref": "#/$defs/currency"},
        "risk_price": {"type": ["string", "null"], "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
        "risk_price_source": {"enum": ["LIMIT_PRICE", "MARKET_WORST_CASE", "UNAVAILABLE"]},
        "reference_price": {"type": ["string", "null"], "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
        "price_deviation_bps": {"type": ["integer", "null"], "minimum": 0},
        "upper_price_limit": {"type": ["string", "null"], "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
        "lower_price_limit": {"type": ["string", "null"], "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:quantiqmt:contract:risk-rule-set:v1",
  "title": "RiskRuleSetV1",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "rule_set_id", "rule_set_version", "content_hash", "valuation_currency", "hard_limit_policy_version", "hard_limit_policy_hash", "evaluation_timeout_us", "freshness_limits_ms", "system_hard_limits", "reduce_only_policy", "rules"],
  "properties": {
    "schema_version": {"const": 1},
    "rule_set_id": {"type": "string", "format": "uuid", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
    "rule_set_version": {"type": "string", "minLength": 1, "maxLength": 64},
    "content_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "valuation_currency": {"$ref": "#/$defs/currency"},
    "hard_limit_policy_version": {"type": "string", "minLength": 1, "maxLength": 64},
    "hard_limit_policy_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "evaluation_timeout_us": {"type": "integer", "minimum": 1, "maximum": 4000},
    "freshness_limits_ms": {
      "type": "object",
      "additionalProperties": false,
      "required": ["account", "portfolio", "market"],
      "properties": {
        "account": {"type": "integer", "minimum": 0, "maximum": 86400000},
        "portfolio": {"type": "integer", "minimum": 0, "maximum": 86400000},
        "market": {"type": "integer", "minimum": 0, "maximum": 86400000}
      }
    },
    "system_hard_limits": {
      "type": "object",
      "additionalProperties": false,
      "required": ["allow_new_risk", "max_order_quantity", "max_order_notional", "max_price_deviation_bps", "max_projected_gross_exposure", "max_projected_net_exposure_abs", "max_projected_leverage", "max_daily_loss", "activity_window_ms", "max_order_count_window", "max_cancel_ratio_bps"],
      "properties": {
        "allow_new_risk": {"type": "boolean"},
        "max_order_quantity": {"type": "integer", "minimum": 1},
        "max_order_notional": {"$ref": "#/$defs/nonNegativeDecimal"},
        "max_price_deviation_bps": {"type": "integer", "minimum": 0},
        "max_projected_gross_exposure": {"$ref": "#/$defs/nonNegativeDecimal"},
        "max_projected_net_exposure_abs": {"$ref": "#/$defs/nonNegativeDecimal"},
        "max_projected_leverage": {"$ref": "#/$defs/nonNegativeDecimal"},
        "max_daily_loss": {"$ref": "#/$defs/nonNegativeDecimal"},
        "activity_window_ms": {"type": "integer", "minimum": 1, "maximum": 86400000},
        "max_order_count_window": {"type": "integer", "minimum": 1},
        "max_cancel_ratio_bps": {"type": "integer", "minimum": 0, "maximum": 10000}
      }
    },
    "reduce_only_policy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["enabled", "exempt_rule_ids"],
      "properties": {
        "enabled": {"type": "boolean"},
        "exempt_rule_ids": {"type": "array", "items": {"type": "string", "pattern": "^[A-Z0-9][A-Z0-9_.-]{0,127}$"}, "uniqueItems": true, "maxItems": 256}
      }
    },
    "rules": {"type": "array", "items": {"$ref": "#/$defs/rule"}, "maxItems": 4096}
  },
  "$defs": {
    "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
    "nonNegativeDecimal": {"type": "string", "pattern": "^(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
    "limit": {
      "oneOf": [
        {"type": "object", "additionalProperties": false, "required": ["kind", "value", "currency"], "properties": {"kind": {"const": "DECIMAL"}, "value": {"$ref": "#/$defs/nonNegativeDecimal"}, "currency": {"type": ["string", "null"], "pattern": "^[A-Z]{3}$"}}},
        {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "INTEGER"}, "value": {"type": "integer", "minimum": 0}}},
        {"type": "object", "additionalProperties": false, "required": ["kind", "value"], "properties": {"kind": {"const": "BOOLEAN"}, "value": {"type": "boolean"}}},
        {"type": "object", "additionalProperties": false, "required": ["kind", "values"], "properties": {"kind": {"const": "STRING_SET"}, "values": {"type": "array", "items": {"type": "string", "minLength": 1, "maxLength": 128}, "minItems": 1, "maxItems": 10000, "uniqueItems": true}}}
      ]
    },
    "rule": {
      "type": "object",
      "additionalProperties": false,
      "required": ["rule_id", "scope", "scope_id", "priority", "metric", "operator", "limit", "reduction_exception"],
      "properties": {
        "rule_id": {"type": "string", "pattern": "^[A-Z0-9][A-Z0-9_.-]{0,127}$"},
        "scope": {"enum": ["SYSTEM", "ACCOUNT", "PORTFOLIO", "STRATEGY", "INSTRUMENT"]},
        "scope_id": {"type": ["string", "null"], "minLength": 1, "maxLength": 128},
        "priority": {"type": "integer", "minimum": 0, "maximum": 1000000},
        "metric": {"enum": ["TRADING_ENABLED", "INSTRUMENT_ALLOWED", "ORDER_QUANTITY", "ORDER_NOTIONAL", "PRICE_DEVIATION_BPS", "AVAILABLE_CASH", "POSITION_QUANTITY", "PROJECTED_GROSS_EXPOSURE", "PROJECTED_NET_EXPOSURE_ABS", "PROJECTED_LEVERAGE", "DAILY_LOSS", "ORDER_COUNT_WINDOW", "CANCEL_RATIO_BPS"]},
        "operator": {"enum": ["BOOLEAN_TRUE", "IN_SET", "MAX", "MIN"]},
        "limit": {"$ref": "#/$defs/limit"},
        "reduction_exception": {"enum": ["NEVER", "ALLOW_IF_VERIFIED"]}
      },
      "allOf": [
        {"if": {"properties": {"scope": {"const": "SYSTEM"}}}, "then": {"properties": {"scope_id": {"type": "null"}}}, "else": {"properties": {"scope_id": {"type": "string"}}}},
        {"if": {"properties": {"metric": {"enum": ["ORDER_NOTIONAL", "AVAILABLE_CASH", "PROJECTED_GROSS_EXPOSURE", "PROJECTED_NET_EXPOSURE_ABS", "DAILY_LOSS"]}}, "required": ["metric"]}, "then": {"properties": {"limit": {"type": "object", "required": ["kind", "value", "currency"], "properties": {"kind": {"const": "DECIMAL"}, "currency": {"$ref": "#/$defs/currency"}}}}}},
        {"if": {"properties": {"metric": {"const": "PROJECTED_LEVERAGE"}}, "required": ["metric"]}, "then": {"properties": {"limit": {"type": "object", "required": ["kind", "value", "currency"], "properties": {"kind": {"const": "DECIMAL"}, "currency": {"type": "null"}}}}}}
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:quantiqmt:internal:reconciliation:v1",
  "title": "ReconciliationContractV1",
  "oneOf": [
    {"$ref": "#/$defs/reconciliationCase"},
    {"$ref": "#/$defs/caseTransition"},
    {"$ref": "#/$defs/repairCommand"},
    {"$ref": "#/$defs/repairResult"}
  ],
  "$defs": {
    "uuid": {"type": "string", "format": "uuid", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
    "timestamp": {"type": "string", "format": "date-time", "pattern": "Z$"},
    "hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
    "decimal": {"type": "string", "pattern": "^-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$", "not": {"pattern": "^-0(?:\\.0+)?$"}},
    "nonZeroDecimal": {"type": "string", "pattern": "^-?(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
    "caseKey": {
      "type": "object",
      "additionalProperties": false,
      "required": ["broker", "account_id", "trading_day", "scope_id", "reason_code"],
      "properties": {
        "broker": {"type": "string", "minLength": 1, "maxLength": 64},
        "account_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "trading_day": {"type": "string", "format": "date"},
        "scope_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "reason_code": {"enum": ["CASH_MISMATCH", "POSITION_QUANTITY_MISMATCH", "POSITION_COST_MISMATCH", "TRADE_MISSING_INTERNAL", "TRADE_MISSING_BROKER", "LEDGER_BALANCE_INVALID", "SNAPSHOT_INVALID", "REPAIR_OUTCOME_UNKNOWN"]}
      }
    },
    "differenceValue": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "value", "currency", "instrument_id"],
      "properties": {
        "kind": {"enum": ["MONEY", "QUANTITY", "TEXT"]},
        "value": {"type": ["string", "null"], "maxLength": 256},
        "currency": {"type": ["string", "null"], "pattern": "^[A-Z]{3}$"},
        "instrument_id": {"type": ["string", "null"], "maxLength": 64}
      }
    },
    "difference": {
      "type": "object",
      "additionalProperties": false,
      "required": ["field", "internal_value", "broker_value", "delta"],
      "properties": {
        "field": {"enum": ["CASH", "POSITION_QUANTITY", "POSITION_COST", "TRADE", "LEDGER_BALANCE", "SNAPSHOT"]},
        "internal_value": {"$ref": "#/$defs/differenceValue"},
        "broker_value": {"$ref": "#/$defs/differenceValue"},
        "delta": {"$ref": "#/$defs/differenceValue"}
      }
    },
    "evidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["evidence_id", "case_version", "internal_snapshot_id", "internal_checksum", "internal_checkpoint", "broker_snapshot_id", "broker_observed_at", "broker_sequence", "captured_at", "expires_at"],
      "properties": {
        "evidence_id": {"$ref": "#/$defs/uuid"},
        "case_version": {"type": "integer", "minimum": 1},
        "internal_snapshot_id": {"$ref": "#/$defs/uuid"},
        "internal_checksum": {"$ref": "#/$defs/hash"},
        "internal_checkpoint": {"type": "integer", "minimum": 0},
        "broker_snapshot_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "broker_observed_at": {"$ref": "#/$defs/timestamp"},
        "broker_sequence": {"type": ["integer", "null"], "minimum": 0},
        "captured_at": {"$ref": "#/$defs/timestamp"},
        "expires_at": {"$ref": "#/$defs/timestamp"}
      }
    },
    "audit": {
      "type": "object",
      "additionalProperties": false,
      "required": ["created_by", "created_at", "correlation_id", "causation_id", "last_transition_id", "updated_at"],
      "properties": {
        "created_by": {"type": "string", "minLength": 1, "maxLength": 128},
        "created_at": {"$ref": "#/$defs/timestamp"},
        "correlation_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "causation_id": {"type": ["string", "null"], "maxLength": 128},
        "last_transition_id": {"anyOf": [{"$ref": "#/$defs/uuid"}, {"type": "null"}]},
        "updated_at": {"$ref": "#/$defs/timestamp"}
      }
    },
    "reconciliationCase": {
      "type": "object",
      "additionalProperties": false,
      "required": ["dto_type", "schema_version", "case_id", "case_key", "case_version", "state", "severity", "differences", "evidence", "owner", "deadline_at", "approval_required", "audit"],
      "properties": {
        "dto_type": {"const": "RECONCILIATION_CASE"},
        "schema_version": {"const": 1},
        "case_id": {"$ref": "#/$defs/uuid"},
        "case_key": {"$ref": "#/$defs/caseKey"},
        "case_version": {"type": "integer", "minimum": 1},
        "state": {"enum": ["OPEN", "INVESTIGATING", "PROPOSED", "APPROVED", "REJECTED", "APPLYING", "UNKNOWN", "RESOLVED", "FAILED"]},
        "severity": {"enum": ["P0", "P1", "P2", "P3"]},
        "differences": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/difference"}},
        "evidence": {"$ref": "#/$defs/evidence"},
        "owner": {"type": ["string", "null"], "maxLength": 128},
        "deadline_at": {"$ref": "#/$defs/timestamp"},
        "approval_required": {"type": "boolean"},
        "audit": {"$ref": "#/$defs/audit"}
      },
      "allOf": [
        {"if": {"properties": {"severity": {"enum": ["P0", "P1"]}}, "required": ["severity"]}, "then": {"properties": {"approval_required": {"const": true}}}}
      ]
    },
    "caseTransition": {
      "type": "object",
      "additionalProperties": false,
      "required": ["dto_type", "schema_version", "transition_id", "case_id", "expected_case_version", "resulting_case_version", "from_state", "to_state", "event", "actor_id", "reason_code", "evidence_id", "occurred_at"],
      "properties": {
        "dto_type": {"const": "CASE_TRANSITION"},
        "schema_version": {"const": 1},
        "transition_id": {"$ref": "#/$defs/uuid"},
        "case_id": {"$ref": "#/$defs/uuid"},
        "expected_case_version": {"type": "integer", "minimum": 1},
        "resulting_case_version": {"type": "integer", "minimum": 2},
        "from_state": {"enum": ["OPEN", "INVESTIGATING", "PROPOSED", "APPROVED", "REJECTED", "APPLYING", "UNKNOWN", "RESOLVED", "FAILED"]},
        "to_state": {"enum": ["OPEN", "INVESTIGATING", "PROPOSED", "APPROVED", "REJECTED", "APPLYING", "UNKNOWN", "RESOLVED", "FAILED"]},
        "event": {"enum": ["Assign", "ProposeRepair", "Approve", "Reject", "Apply", "ApplyUncertain", "VerifyResolved", "ApplyFailed", "ReconcileOutcome", "Reinvestigate"]},
        "actor_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "reason_code": {"type": "string", "minLength": 1, "maxLength": 128},
        "evidence_id": {"$ref": "#/$defs/uuid"},
        "occurred_at": {"$ref": "#/$defs/timestamp"}
      }
    },
    "authorization": {
      "type": "object",
      "additionalProperties": false,
      "required": ["principal_id", "role", "authorized", "policy_version", "fencing_token", "authorized_at"],
      "properties": {
        "principal_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "role": {"enum": ["RECONCILIATION_ENGINE", "OPERATIONS_APPROVER", "RISK_APPROVER"]},
        "authorized": {"type": "boolean"},
        "policy_version": {"type": "string", "minLength": 1, "maxLength": 64},
        "fencing_token": {"type": "integer", "minimum": 1},
        "authorized_at": {"$ref": "#/$defs/timestamp"}
      }
    },
    "approval": {
      "type": "object",
      "additionalProperties": false,
      "required": ["approval_id", "approver_id", "decision", "policy_version", "approved_case_version", "approved_evidence_id", "approved_at"],
      "properties": {
        "approval_id": {"$ref": "#/$defs/uuid"},
        "approver_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "decision": {"const": "APPROVE"},
        "policy_version": {"type": "string", "minLength": 1, "maxLength": 64},
        "approved_case_version": {"type": "integer", "minimum": 1},
        "approved_evidence_id": {"$ref": "#/$defs/uuid"},
        "approved_at": {"$ref": "#/$defs/timestamp"}
      }
    },
    "repairEntry": {
      "type": "object",
      "additionalProperties": false,
      "required": ["ledger_account_id", "direction", "amount", "currency", "instrument_id"],
      "properties": {
        "ledger_account_id": {"$ref": "#/$defs/uuid"},
        "direction": {"enum": ["DEBIT", "CREDIT"]},
        "amount": {"type": "string", "pattern": "^(?=.*[1-9])(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?$"},
        "currency": {"$ref": "#/$defs/currency"},
        "instrument_id": {"type": ["string", "null"], "maxLength": 64}
      }
    },
    "sourceEvidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["evidence_id", "internal_checkpoint", "broker_snapshot_id", "broker_sequence"],
      "properties": {
        "evidence_id": {"$ref": "#/$defs/uuid"},
        "internal_checkpoint": {"type": "integer", "minimum": 0},
        "broker_snapshot_id": {"type": "string", "minLength": 1, "maxLength": 128},
        "broker_sequence": {"type": ["integer", "null"], "minimum": 0}
      }
    },
    "repairFact": {
      "type": "object",
      "additionalProperties": false,
      "required": ["fact_id", "fact_type", "reason_code", "source_evidence", "quantity_correction", "monetary_adjustment", "compensates_fact_id", "entries"],
      "properties": {
        "fact_id": {"$ref": "#/$defs/uuid"},
        "fact_type": {"enum": ["QUANTITY_CORRECTION", "MONETARY_ADJUSTMENT", "COMPENSATING_FACT"]},
        "reason_code": {"type": "string", "minLength": 1, "maxLength": 128},
        "source_evidence": {"$ref": "#/$defs/sourceEvidence"},
        "quantity_correction": {
          "type": ["object", "null"],
          "additionalProperties": false,
          "required": ["instrument_id", "currency", "quantity_delta", "cost_basis_delta"],
          "properties": {
            "instrument_id": {"type": "string", "minLength": 1, "maxLength": 64},
            "currency": {"$ref": "#/$defs/currency"},
            "quantity_delta": {"type": "integer", "not": {"const": 0}},
            "cost_basis_delta": {"$ref": "#/$defs/decimal"}
          }
        },
        "monetary_adjustment": {
          "type": ["object", "null"],
          "additionalProperties": false,
          "required": ["currency", "amount_delta"],
          "properties": {"currency": {"$ref": "#/$defs/currency"}, "amount_delta": {"$ref": "#/$defs/nonZeroDecimal"}}
        },
        "compensates_fact_id": {"anyOf": [{"$ref": "#/$defs/uuid"}, {"type": "null"}]},
        "entries": {"type": "array", "minItems": 2, "items": {"$ref": "#/$defs/repairEntry"}}
      },
      "oneOf": [
        {"properties": {"fact_type": {"const": "QUANTITY_CORRECTION"}, "quantity_correction": {"type": "object"}, "monetary_adjustment": {"type": "null"}, "compensates_fact_id": {"type": "null"}}},
        {"properties": {"fact_type": {"const": "MONETARY_ADJUSTMENT"}, "quantity_correction": {"type": "null"}, "monetary_adjustment": {"type": "object"}, "compensates_fact_id": {"type": "null"}}},
        {"properties": {"fact_type": {"const": "COMPENSATING_FACT"}, "compensates_fact_id": {"$ref": "#/$defs/uuid"}}}
      ]
    },
    "repairAction": {
      "type": "object",
      "additionalProperties": false,
      "required": ["action_id", "operation", "target", "payload", "expected_source_version"],
      "properties": {
        "action_id": {"$ref": "#/$defs/uuid"},
        "operation": {"enum": ["APPEND_ADJUSTMENT", "APPEND_COMPENSATING_FACT"]},
        "target": {"const": "LEDGER"},
        "payload": {"$ref": "#/$defs/repairFact"},
        "expected_source_version": {"type": "integer", "minimum": 0}
      },
      "allOf": [
        {"if": {"properties": {"operation": {"const": "APPEND_COMPENSATING_FACT"}}, "required": ["operation"]}, "then": {"properties": {"payload": {"properties": {"fact_type": {"const": "COMPENSATING_FACT"}}}}}}
      ]
    },
    "repairCommand": {
      "type": "object",
      "additionalProperties": false,
      "required": ["dto_type", "schema_version", "command_id", "idempotency_key", "command_fingerprint", "case_id", "case_key", "case_severity", "expected_case_version", "expected_portfolio_version", "fencing_token", "mode", "evidence", "authorization", "approval", "actions", "deadline_at", "requested_at"],
      "properties": {
        "dto_type": {"const": "REPAIR_COMMAND"},
        "schema_version": {"const": 1},
        "command_id": {"$ref": "#/$defs/uuid"},
        "idempotency_key": {"type": "string", "minLength": 1, "maxLength": 256},
        "command_fingerprint": {"$ref": "#/$defs/hash"},
        "case_id": {"$ref": "#/$defs/uuid"},
        "case_key": {"$ref": "#/$defs/caseKey"},
