          "recovery_barrier_version": {"type": ["integer", "null"], "minimum": 1, "maximum": 9007199254740991},
          "recovery_barrier_checksum": {"type": ["string", "null"], "pattern": "^[0-9a-f]{64}$"},
          "recovery_evidence_digest": {"type": ["string", "null"], "pattern": "^[0-9a-f]{64}$"}
        }},
        {"$ref": "#/$defs/scopeRule"},
        {"if": {"properties": {"desired_state": {"const": "ON"}}, "required": ["desired_state"]}, "then": {"properties": {"recovery_evidence_reference": {"type": "null"}, "recovery_barrier_generation": {"type": "null"}, "recovery_barrier_version": {"type": "null"}, "recovery_barrier_checksum": {"type": "null"}, "recovery_evidence_digest": {"type": "null"}}}},
        {"if": {"properties": {"desired_state": {"const": "OFF"}}, "required": ["desired_state"]}, "then": {"properties": {"recovery_evidence_reference": {"type": "string", "minLength": 1}, "recovery_barrier_generation": {"type": "integer", "minimum": 1}, "recovery_barrier_version": {"type": "integer", "minimum": 1}, "recovery_barrier_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"}, "recovery_evidence_digest": {"type": "string", "pattern": "^[0-9a-f]{64}$"}}}}
