        {"if": {"properties": {"outcome": {"const": "REJECTED"}}, "required": ["outcome"]}, "then": {"properties": {"effective_state": {"enum": ["ON", "OFF"]}, "reconciliation_required": {"const": false}, "applied_at": {"type": "null"}, "effect_evidence": {"properties": {"ack_ids": {"maxItems": 0}}}}}},
        {"if": {"properties": {"outcome": {"const": "UNKNOWN"}}, "required": ["outcome"]}, "then": {"properties": {"effective_state": {"const": "UNKNOWN"}, "reconciliation_required": {"const": true}, "applied_at": {"type": "null"}}}}
      ]
    },
    "leaderLease": {
      "unevaluatedProperties": false,
      "allOf": [
        {"$ref": "#/$defs/base"},
        {"type": "object", "required": ["dto_type", "lease_id", "holder_id", "epoch", "fencing_token", "issued_at", "expires_at", "renew_deadline_at", "status"], "properties": {
          "dto_type": {"const": "LEADER_LEASE"},
          "lease_id": {"type": "string", "minLength": 1},
          "holder_id": {"type": "string", "minLength": 1},
          "epoch": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
          "fencing_token": {"type": "string", "minLength": 16, "maxLength": 256},
