          "expires_at": {"$ref": "#/$defs/controlTimestamp"},
          "renew_deadline_at": {"$ref": "#/$defs/controlTimestamp"},
          "status": {"enum": ["ACTIVE", "EXPIRED", "REVOKED", "TRANSFER_PENDING"]}
        }}
