    "recoveryEvidence": {
      "type": "object", "additionalProperties": false,
      "required": ["config_version", "config_checksum", "market_watermark", "audit_watermark", "reconciliation_case_count", "component_versions", "component_checksums", "lease_id", "leader_id", "lease_authority_version", "lease_epoch", "fencing_token", "lease_expires_at", "audit_outbox_position", "audit_inbox_position", "audit_checksum", "audit_lag", "audit_healthy", "market_calendar_version", "market_calendar_checksum", "market_session_id", "market_session_state", "market_policy_version", "market_policy_checksum", "market_tzdb_version", "market_tzdb_checksum", "market_source_version", "market_quality", "unresolved_gap_count", "market_fresh_until", "reconciliation_version", "reconciliation_checksum", "critical_lag_policy_version", "critical_lag_policy_checksum", "critical_lag_threshold", "critical_lag_measurement_source", "critical_lag_window_seconds", "critical_lag_recovery_window_seconds", "critical_lag_current", "component_generations", "component_health", "observed_at"],
      "properties": {
        "config_version": {"type": "string", "minLength": 1},
        "config_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "market_watermark": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "audit_watermark": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "reconciliation_case_count": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "component_versions": {"type": "object", "minProperties": 1, "additionalProperties": {"type": "string", "minLength": 1}},
        "component_checksums": {"type": "object", "minProperties": 1, "additionalProperties": {"type": "string", "pattern": "^[0-9a-f]{64}$"}},
        "lease_id": {"type": "string", "minLength": 1},
        "leader_id": {"type": "string", "minLength": 1},
        "lease_authority_version": {"type": "string", "minLength": 1},
        "lease_epoch": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
        "fencing_token": {"type": "string", "minLength": 16},
        "lease_expires_at": {"$ref": "#/$defs/controlTimestamp"},
        "audit_outbox_position": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "audit_inbox_position": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "audit_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "audit_lag": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "audit_healthy": {"type": "boolean"},
        "market_calendar_version": {"type": "string", "minLength": 1},
        "market_calendar_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "market_session_id": {"type": "string", "minLength": 1},
        "market_session_state": {"type": "string", "minLength": 1},
        "market_policy_version": {"type": "string", "minLength": 1},
        "market_policy_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "market_tzdb_version": {"type": "string", "minLength": 1},
        "market_tzdb_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "market_source_version": {"type": "string", "minLength": 1},
        "market_quality": {"enum": ["NORMAL", "DEGRADED", "STALE", "GAP", "UNAVAILABLE"]},
        "unresolved_gap_count": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "market_fresh_until": {"$ref": "#/$defs/controlTimestamp"},
        "reconciliation_version": {"type": "string", "minLength": 1},
        "reconciliation_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "critical_lag_policy_version": {"type": "string", "minLength": 1},
        "critical_lag_policy_checksum": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "critical_lag_threshold": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "critical_lag_measurement_source": {"type": "string", "minLength": 1},
        "critical_lag_window_seconds": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
        "critical_lag_recovery_window_seconds": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
        "critical_lag_current": {"type": "integer", "minimum": 0, "maximum": 9007199254740991},
        "component_generations": {"type": "object", "minProperties": 1, "additionalProperties": {"type": "integer", "minimum": 1, "maximum": 9007199254740991}},
        "component_health": {"type": "object", "minProperties": 1, "additionalProperties": {"enum": ["HEALTHY", "DEGRADED", "UNAVAILABLE", "RECOVERING"]}},
        "observed_at": {"$ref": "#/$defs/controlTimestamp"}
      }
    },
    "recoveryBarrier": {
      "unevaluatedProperties": false,
      "allOf": [
        {"$ref": "#/$defs/base"},
        {"type": "object", "required": ["dto_type", "barrier_id", "state", "generation", "opened_at", "evidence", "required_evidence", "invalidation_reason"], "properties": {
          "dto_type": {"const": "RECOVERY_BARRIER"},
          "barrier_id": {"type": "string", "minLength": 1},
          "state": {"enum": ["CLOSED", "OPEN", "INVALIDATED"]},
          "generation": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
          "opened_at": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/controlTimestamp"}]},
