          "required_evidence": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"enum": ["CONFIG_VERIFIED", "MARKET_FRESH", "AUDIT_AVAILABLE", "RECONCILIATION_COMPLETE", "LEASE_FENCED", "OUTBOX_HEALTHY"]}},
          "invalidation_reason": {"type": ["string", "null"], "enum": [null, "MARKET_STALE", "AUDIT_UNAVAILABLE", "LEASE_EXPIRED", "COMPONENT_UNHEALTHY", "CONFIG_MISMATCH", "RECONCILIATION_BLOCKED", "MANUAL_AUTHORIZED"]}
